const fs = require('fs');
const TOKEN = fs.readFileSync('/tmp/owner_token.txt', 'utf8').trim();
const https = require('https');
const req = https.request({ hostname: 'api.ivxholding.com', path: '/api/ivx/render-diagnostic?limit=5', method: 'GET', headers: { 'Authorization': 'Bearer ' + TOKEN, 'Accept': 'application/json' }, timeout: 15000 }, res => {
  let data = '';
  res.on('data', chunk => data += chunk);
  res.on('end', () => {
    try {
      const r = JSON.parse(data);
      console.log('Workspace:', r.service?.workspace?.name || r.service?.serviceDetails?.workspace);
      console.log('Service plan:', r.service?.serviceDetails?.plan, 'buildPlan:', r.service?.serviceDetails?.buildPlan);
      console.log('Build minutes:', JSON.stringify(r.service?.buildMinutes || 'not exposed'));
      console.log('Latest deploys:');
      for (const d of (r.recentDeploys || [])) {
        console.log(d.id, d.status, d.commitSha?.slice(0,7), d.failureReason || 'null', 'created:', d.createdAt, 'finished:', d.finishedAt);
      }
    } catch(e) { console.log('parse error:', data.slice(0,2000)); }
  });
});
req.on('error', err => console.log('ERROR:', err.message));
req.end();
" 2>&1

