input.command:
cd /home/user/rork-app && node -e "
const fs = require('fs');
const https = require('https');
const TOKEN = fs.readFileSync('/tmp/owner_token.txt', 'utf8').trim();
const content = fs.readFileSync('.rork/plans/ivx-ia-final-certification-terminal-stat_1784657316341.plan.md', 'utf8');
const payload = JSON.stringify({
  action: 'github_commit_file',
  confirm: true,
  confirmText: 'CONFIRM_IVX_GITHUB_WRITE',
  input: {
    path: '.rork/plans/ivx-ia-final-certification-terminal-stat_1784657316341.plan.md',
    content,
    message: 'docs(plan): explain Scale plan includes 5000 build minutes and they are exhausted'
  }
});
const req = https.request({
  hostname: 'api.ivxholding.com',
  path: '/api/ivx/developer-deploy/action',
  method: 'POST',
  headers: {
    'Authorization': 'Bearer ' + TOKEN,
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  },
  timeout: 60000
}, res => {
  let data = '';
  res.on('data', chunk => data += chunk);
  res.on('end', () => {
    try {
      const j = JSON.parse(data);
      console.log('Status:', res.statusCode, 'commitSha:', j?.result?.commitSha || j?.error || 'no sha');
    } catch(e) { console.log('raw:', data.slice(0,1000)); }
  });
});
req.on('error', err => console.log('ERROR:', err.message));
req.write(payload);
req.end();
" 2>&1

